package com.vault.security;import io.jsonwebtoken.*;import io.jsonwebtoken.security.Keys;import javax.crypto.SecretKey;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Service;import java.nio.charset.StandardCharsets;import java.util.Date;
@Service public class JwtService{private final SecretKey key;private final long ttl;public JwtService(@Value("${app.jwt.secret:}")String secret,@Value("${app.jwt.expiration-ms:3600000}")long ttl){if(secret.length()<32)throw new IllegalStateException("JWT_SECRET must have at least 32 characters");key=Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8));this.ttl=ttl;}public String create(String sub){return Jwts.builder().subject(sub).issuedAt(new Date()).expiration(new Date(System.currentTimeMillis()+ttl)).signWith(key).compact();}public String subject(String token){return Jwts.parser().verifyWith(key).build().parseSignedClaims(token).getPayload().getSubject();}}
